# Categorias de custo (CMV, CSP) que estavam em Despesas com Vendas passam para o grupo Custos,
# que o DRE mostra junto do CMV, e não como despesa operacional.
def mover_custos(apps, schema_editor):
    Categoria = apps.get_model("financeiro", "FinanceiroCategoria")
    for categoria in Categoria.objects.filter(grupo_dre="DESPESA_VENDAS"):
        if categoria.nome.strip().upper() in ("CMV", "CSP", "CMV/CSP", "CPV"):
            categoria.grupo_dre = "CUSTOS"
            categoria.save(update_fields=["grupo_dre"])


